import * as T from './vendor/three.module.js';
import {mergeStaticChildren} from './merge-static.mjs';
// Same full-suspension bike in the shed, at the start and under the first-person camera.
export function buildMountainBike(){const g=new T.Group();g.userData.kind='detailed-alpine-mountain-bike';const mat=(color,e={})=>new T.MeshStandardMaterial({color,roughness:.55,...e}),frame=mat('#35574b',{metalness:.4}),rubber=mat('#242d2b',{roughness:1}),metal=mat('#a8b2ad',{metalness:.8}),gold=mat('#b79853',{metalness:.6}),black=mat('#38413e');
 const mesh=(geo,m,x=0,y=0,z=0)=>{const o=new T.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;g.add(o);return o;};
 const rod=(a,b,r,m)=>{const u=new T.Vector3(...a),v=new T.Vector3(...b),d=v.clone().sub(u),o=mesh(new T.CylinderGeometry(r,r,d.length(),9),m);o.position.copy(u.add(v).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;};
 for(const x of[-.62,.62]){mesh(new T.TorusGeometry(.35,.047,9,32),rubber,x,.4,0);mesh(new T.TorusGeometry(.29,.014,5,28),metal,x,.4,0);for(let i=0;i<16;i++){const a=i*Math.PI/8;rod([x,.4,0],[x+Math.cos(a)*.3,.4+Math.sin(a)*.3,0],.0035,metal);}mesh(new T.CylinderGeometry(.035,.035,.15,10),metal,x,.4,0).rotation.x=Math.PI/2;mesh(new T.TorusGeometry(.13,.015,5,18),metal,x,.4,.07);for(let i=0;i<32;i++){const a=i*Math.PI/16;const tread=mesh(new T.BoxGeometry(.045,.025,.085),rubber,x+Math.sin(a)*.39,.4+Math.cos(a)*.39,0);tread.rotation.z=-a;}}
 for(const[a,b]of [[[-.62,.4,0],[-.12,.87,0]],[[-.62,.4,0],[0,.38,0]],[[0,.38,0],[-.12,.87,0]],[[-.12,.87,0],[.36,.97,0]],[[.36,.97,0],[0,.38,0]]])rod(a,b,.029,frame);
 for(const z of[-.065,.065]){rod([.62,.4,z],[.45,.77,z],.028,black);rod([.45,.77,z],[.36,.97,z],.019,gold);}rod([-.2,.7,0],[.1,.58,0],.033,black);for(let i=0;i<7;i++)mesh(new T.TorusGeometry(.045,.008,5,10),metal,-.16+i*.035,.68-i*.014,0).rotation.y=Math.PI/2;
 rod([-.12,.87,0],[-.12,1.03,0],.022,metal);mesh(new T.BoxGeometry(.28,.06,.15),rubber,-.16,1.05,0);rod([.36,.97,0],[.4,1.13,0],.025,black);rod([.4,1.13,-.36],[.4,1.13,.36],.022,black);for(const z of[-.3,.3]){rod([.4,1.13,z-.07],[.4,1.13,z+.07],.03,rubber);rod([.36,1.11,z*.7],[.31,1.07,z*.65],.015,metal);}for(const z of[-.13,.13]){rod([0,.38,0],[z,.25,z],.014,metal);mesh(new T.BoxGeometry(.13,.035,.12),black,z,.25,z);}rod([-.62,.41,.04],[0,.38,.04],.007,metal);
 const hose=new T.CatmullRomCurve3([[.4,1.12,.24],[.18,.9,.19],[.48,.63,.11],[.62,.43,.08]].map(v=>new T.Vector3(...v)));mesh(new T.TubeGeometry(hose,18,.008,5,false),rubber);mergeStaticChildren(g);return g;}
